import React, { useState } from 'react';

interface VerificationModalProps {
  venueName: string;
  onClose: () => void;
}

export const VerificationModal: React.FC<VerificationModalProps> = ({ venueName, onClose }) => {
  const [isRequested, setIsRequested] = useState(false);
  const domainAddress = "slovesny.ru";
  const hrefWebSite = `https://${domainAddress}/`;

  const verifyCafe = async () => {
    const telegramInitData = window.Telegram?.WebApp?.initData || '';
  
    const response = await fetch(`${hrefWebSite}api-zvuk/cafes/verify-request`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${telegramInitData}`
      }
    });
  
    const result = await response.json();
    if (!result.success) {
      throw new Error(result.error || 'Ошибка при отправке запроса на верификацию');
    }
  
    return true;
  };

  const handleRequestCall = async () => {
    console.log("handleRequestCall() called");
    setIsRequested(true);
    await verifyCafe();
    console.log("verifyCafe() awaited");
  };

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-10000 flex items-center justify-center p-4 animate-fade-in">
      <div 
        style={{ background: '#0d1222', border: '1px solid rgba(255, 255, 255, 0.1)' }}
        className="rounded-3xl p-6 max-w-sm w-full text-center shadow-2xl relative flex flex-col items-center gap-4 text-white"
      >
        {/* Кнопка закрытия */}
        <button 
          onClick={onClose}
          className="absolute top-4 right-4 text-slate-400 hover:text-white text-lg bg-transparent border-none cursor-pointer"
        >
          ✕
        </button>

        <div className="w-14 h-14 rounded-2xl bg-pink-500/10 border border-pink-500/20 flex items-center justify-center text-3xl mt-2">
          📞
        </div>

        <div>
          <h3 className="text-lg font-black tracking-tight mb-2">
            Прохождение разовой верификации
          </h3>
          <p className="text-xs text-slate-400 leading-relaxed">
            Мы звоним на номер телефона, указанный в картах/соцсетях{' '}
            <span className="text-pink-400 font-bold">{venueName || 'Заведения'}</span>, чтобы избежать баловства.
          </p>
        </div>

        {/* Кнопка "Заказать звонок" */}
        <button
          onClick={handleRequestCall}
          disabled={isRequested}
          className={`w-full py-3.5 rounded-2xl font-bold text-sm transition-all active:scale-95 border-none cursor-pointer ${
            isRequested
              ? 'bg-slate-800 text-slate-500 cursor-not-allowed'
              : 'bg-pink-500 hover:bg-pink-600 text-white shadow-lg shadow-pink-500/25'
          }`}
        >
          {isRequested ? 'Заявка отправлена ✅' : 'Заказать звонок'}
        </button>

        {/* Инструкция под кнопкой */}
        <p className="text-[11px] text-slate-500 leading-normal">
          Проверьте, что в настройках профиля Телеграм указан <span className="text-slate-300 font-semibold">@username</span>, и нажмите «Заказать звонок»
        </p>
      </div>
    </div>
  );
};

export default VerificationModal;