const handleAcceptApplication = async (orderId, musicianUUId) => {
  // Подтверждение перед выбором
  if (!window.confirm('Вы уверены, что хотите утвердить этого артиста на выступление?')) {
    return;
  }

  try {
    setLoading(true);
    const telegramInitData = window.Telegram?.WebApp?.initData || '';

    const response = await fetch(`${hrefWebSite}api-zvuk/accept-application`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${telegramInitData}`
      },
      body: JSON.stringify({
        orderId,
        musicianUUId
      })
    });

    const data = await response.json();

    if (!response.ok || !data.success) {
      throw new Error(data.error || 'Не удалось утвердить артиста');
    }

    // Показываем уведомление об успехе (если используете Telegram WebApp Alert)
    if (window.Telegram?.WebApp?.showAlert) {
      window.Telegram.WebApp.showAlert('🎉 Артист успешно выбран!');
    } else {
      alert('🎉 Артист успешно выбран!');
    }

    // Перезапрашиваем список гигов, чтобы интерфейс мгновенно обновился
    await fetchMyGigs(false);

  } catch (err) {
    console.error('Ошибка выбора артиста:', err);
    alert(err.message || 'Произошла ошибка при выборе артиста');
  } finally {
    setLoading(false);
  }
};

