const filteredMusicians = (Array.isArray(musiciansList) ? musiciansList : []).filter(m => {
  // 1. Поиск по тексту (имя, инструменты или жанры)
  const query = searchQuery.toLowerCase().trim();
  const matchesSearch = !query || 
    m.name?.toLowerCase().includes(query) ||
    m.instruments?.some(i => i?.toLowerCase().includes(query)) ||
    m.genres?.some(g => g?.toLowerCase().includes(query));

  // 2. Поиск по рейтингу (с дефолтным значением 0, если rating не указан)
  const matchesRating = (m.rating ?? 0) >= selectedRating;

  // 3. Мульти-поиск по инструментам
  const matchesInst = selectedInstruments.length === 0 || 
    m.instruments?.some(i => selectedInstruments.includes(i));

  // 4. Мульти-поиск по жанрам
  const matchesGenre = selectedGenres.length === 0 || 
    m.genres?.some(g => selectedGenres.includes(g));

  return matchesSearch && matchesRating && matchesInst && matchesGenre;
});


