// --- ФУНКЦИЯ ОТПРАВКИ В БД (ПО ВАШЕМУ ШАБЛОНУ) ---
const handleCreateGigSubmit = async (e) => {
  if (e) e.preventDefault();

  setIsSubmittingGig(true);

  try {
    // 1. Формируем timestamp в миллисекундах (для int8 в Postgres)
    const startDateTime = new Date(`${gigForm.date}T${gigForm.time}:00`);
    const beginAtTimestamp = startDateTime.getTime();
    
    // По умолчанию +2 часа длительности
    const durationMs = (Number(gigForm.durationMinutes) || 120) * 60 * 1000;
    const endAtTimestamp = beginAtTimestamp + durationMs;

    // 2. Тело запроса
    const payload = {
      genres: gigForm.genres,           // Массив ['Рок', 'Каверы']
      instruments: gigForm.instruments, // Массив ['Гитара', 'Вокал']
      begin_at: beginAtTimestamp,       // int8
      end_at: endAtTimestamp,           // int8
      price: Number(gigForm.price),     // int2
      status: 'search',
      title: gigForm.title
    };

    // 3. Отправка на ваш бэкенд
    const response = await fetch(`${hrefWebSite}api-zvuk/orders/create`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${window.Telegram?.WebApp?.initData}`
      },
      body: JSON.stringify(payload)
    });

    const result = await response.json();

    if (!result.success) {
      throw new Error(result.error || 'Не удалось создать выступление');
    }

    // 4. Успех
    setShowCreateGigModal(false);
    await fetchMyGigs(true);
    alert('Выступление создано и запущено в поиск! 🚀');

    // Сброс формы (опционально)
    setGigForm({
      genres: [],
      instruments: [],
      date: '2026-06-21',
      time: '17:37',
      durationMinutes: 60,
      price: 350
    });

  } catch (err) {
    console.error('Ошибка сохранения выступления:', err);
    alert(`Ошибка: ${err.message}`);
  } finally {
    setIsSubmittingGig(false);
  }
};

