import React, { useEffect, useRef } from 'react';
import { MapContainer, TileLayer, useMap, useMapEvents } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';

function MapController({ initialCoordinates, onLocationSelect }) {
  const map = useMap();
  const onSelectRef = useRef(onLocationSelect);
  const isInitializingRef = useRef(true);
  const isSelfTriggeredRef = useRef(false);

  useEffect(() => {
    onSelectRef.current = onLocationSelect;
  }, [onLocationSelect]);

  // 1. Центрируем карту ТОЛЬКО если координаты изменились извне (например, из поиска)
  useEffect(() => {
    if (Array.isArray(initialCoordinates) && initialCoordinates.length === 2) {
      const [lat, lng] = initialCoordinates;
      if (!lat || !lng) return;

      const center = map.getCenter();
      // Проверяем разницу: если разница больше ~100 метров, значит это смещение извне
      const distLat = Math.abs(center.lat - lat);
      const distLng = Math.abs(center.lng - lng);

      if (distLat > 0.001 || distLng > 0.001) {
        isSelfTriggeredRef.current = true;
        map.setView([lat, lng], map.getZoom(), { animate: false });
      }
    }
  }, [map, initialCoordinates?.[0], initialCoordinates?.[1]]);

  // 2. Первичная подгонка размеров
  useEffect(() => {
    const timer = setTimeout(() => {
      map.invalidateSize();

      const center = map.getCenter();
      const initialCoords = [
        Number(center.lat.toFixed(6)),
        Number(center.lng.toFixed(6))
      ];

      if (onSelectRef.current) {
        onSelectRef.current(initialCoords, false);
      }

      setTimeout(() => {
        isInitializingRef.current = false;
      }, 200);
    }, 250);

    return () => clearTimeout(timer);
  }, [map]);

  // 3. Отслеживание перемещения пользователем
  useMapEvents({
    moveend: () => {
      // Игнорируем стартовую загрузку и сдвиги, вызванные пропсом initialCoordinates
      if (isInitializingRef.current) return;
      if (isSelfTriggeredRef.current) {
        isSelfTriggeredRef.current = false;
        return;
      }

      const center = map.getCenter();
      const newCoords = [
        Number(center.lat.toFixed(6)),
        Number(center.lng.toFixed(6))
      ];

      if (onSelectRef.current) {
        onSelectRef.current(newCoords, true);
      }
    }
  });

  return null;
}

export default function LocationPickerMap({
  initialCoordinates = [53.9006, 27.5590],
  onLocationSelect
}) {
  const validCoords = Array.isArray(initialCoordinates) && initialCoordinates.length === 2
    ? initialCoordinates
    : [53.9006, 27.5590];

  return (
    <div className="relative w-full h-96 rounded-2xl overflow-hidden border border-white/10 shadow-xl bg-slate-900">
      
      {/* 📍 Прицел по центру */}
      <div className="absolute inset-0 z-1000 pointer-events-none flex items-center justify-center pb-6">
        <div className="flex flex-col items-center animate-pulse">
          <div className="w-8 h-8 rounded-full bg-pink-500 border-2 border-white shadow-lg flex items-center justify-center text-white text-xs">
            📍
          </div>
          <div className="w-2.5 h-1 bg-black/50 rounded-full blur-[1px] mt-0.5"></div>
        </div>
      </div>

      <div className="absolute bottom-2 left-1/2 -translate-x-1/2 z-1000 pointer-events-none bg-slate-900/90 backdrop-blur px-3 py-1 rounded-full border border-white/10 text-[10px] text-slate-300 font-semibold shadow-md whitespace-nowrap">
        Сдвиньте карту под прицел
      </div>

      <MapContainer 
        center={validCoords} 
        zoom={13} 
        style={{ width: '100%', height: '100%' }}
        zoomControl={false}
        attributionControl={false}
      >
        {/* Используем светлую тему */}
        <TileLayer 
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          maxZoom={19}
        />
        <MapController 
          initialCoordinates={validCoords} 
          onLocationSelect={onLocationSelect} 
        />
      </MapContainer>
    </div>
  );
}